#include "gpu-common.h"
#include "preview-shm.h"
int main(int argc,char**argv){nice(7);if(argc!=2||strcmp(argv[1],"--i420"))return 2;mfxSession session=NULL;if(gpuInit(&session,1))return 3;unsigned char*input=malloc(MAX_AU);if(!input)return 3;mfxBitstream bs={0};bs.Data=input;bs.MaxLength=MAX_AU;mfxVideoParam dp={0};mfxFrameAllocResponse pool={0};mfxFrameSurface1 surfaces[64];memset(surfaces,0,sizeof(surfaces));unsigned ns=0;int initialized=0,result=0;for(;;){uint32_t header[2];int n=exactRead(header,8);if(!n)break;if(n<0||header[0]<5||header[0]>MAX_AU||!header[1]||exactRead(input,header[0])!=1){result=4;break;}unsigned publishFrame=!(header[1]&0x80000000U);header[1]&=0x7fffffffU;bs.DataOffset=0;bs.DataLength=header[0];bs.DataFlag=MFX_BITSTREAM_COMPLETE_FRAME;bs.TimeStamp=(mfxU64)header[1]*3600;
 if(!initialized){dp.mfx.CodecId=MFX_CODEC_AVC;dp.AsyncDepth=1;dp.IOPattern=MFX_IOPATTERN_OUT_VIDEO_MEMORY;if(status(pMFXVideoDECODE_DecodeHeader(session,&bs,&dp),"PREVIEW_HEADER")){result=5;break;}mfxFrameInfo*f=&dp.mfx.FrameInfo;if((f->CropW!=1280&&f->CropW!=1920)||f->CropH!=480||f->FourCC!=MFX_FOURCC_NV12||f->PicStruct!=MFX_PICSTRUCT_PROGRESSIVE){result=5;break;}mfxFrameAllocRequest req={0};if(status(pMFXVideoDECODE_QueryIOSurf(session,&dp,&req),"PREVIEW_POOL")){result=5;break;}ns=req.NumFrameSuggested+2;if(ns>64){result=5;break;}req.NumFrameSuggested=ns;if(status(allocVideo(NULL,&req,&pool),"PREVIEW_ALLOC")){result=5;break;}for(unsigned i=0;i<ns;i++){surfaces[i].Info=*f;surfaces[i].Data.MemId=pool.mids[i];}if(status(pMFXVideoDECODE_Init(session,&dp),"PREVIEW_INIT")){result=5;break;}initialized=1;bs.DataOffset=0;bs.DataLength=header[0];fprintf(stderr,"PREVIEW_GPU_READY %ux%u no-resize\n",f->CropW,f->CropH);}
 unsigned j=0;for(;j<ns;j++)if(!surfaces[j].Data.Locked)break;if(j==ns){result=6;break;}mfxFrameSurface1*frame=NULL;mfxSyncPoint sync=NULL;mfxStatus s;unsigned retry=0;do{s=pMFXVideoDECODE_DecodeFrameAsync(session,&bs,&surfaces[j],&frame,&sync);if(s==MFX_WRN_DEVICE_BUSY)usleep(1000);}while((s==MFX_WRN_DEVICE_BUSY||(s==MFX_WRN_VIDEO_PARAM_CHANGED&&!frame))&&++retry<200);if(status(s,"PREVIEW_DECODE")||!frame||!sync||bs.DataLength||frame->Data.TimeStamp!=(mfxU64)header[1]*3600||status(pMFXVideoCORE_SyncOperation(session,sync,1000),"PREVIEW_SYNC")||(publishFrame&&publish(frame))){result=6;break;}printf("%s %u\n",publishFrame?"FRAME":"SKIP",header[1]);fflush(stdout);
 }if(initialized)pMFXVideoDECODE_Close(session);if(pool.mids)freeVideo(NULL,&pool);gpuClose(session);free(input);return result;}
